import{_ as i,a,o as t,U as n}from"./chunks/framework.BS4h1hlk.js";const g=JSON.parse('{"title":"Hello!","description":"","frontmatter":{},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md","lastUpdated":1730649563000}'),o={name:"about/index.md"};function r(l,e,s,c,d,p){return t(),a("div",null,e[0]||(e[0]=[n('<h1 id="hello" tabindex="-1">Hello! <a class="header-anchor" href="#hello" aria-label="Permalink to &quot;Hello!&quot;">​</a></h1><p>I’m a Senior Game Artist and Art Lead specialising in stylised art for casual mobile games. I combine artistic creativity with technical expertise to deliver polished game experiences, taking assets from concept to final implementation in Unity.</p><p>My skills span 2D and 3D art, character and environment design, animation, UI, shaders, lighting, and VFX. With a strong focus on shape language, colour, and composition, I create cohesive, engaging visuals that balance artistic quality with production needs.</p><p>I’m passionate about technical art, developing tools, optimising workflows, and solving Unity challenges to bring creative ideas to life efficiently. As an Art Lead, I’ve led art production, mentored artists, managed external contributors, and collaborated with multidisciplinary teams to maintain a consistent visual direction.</p><p>I’m always exploring new techniques, procedural workflows, and new tools to push creative possibilities and improve production.</p><p>For me, great game art goes beyond aesthetics - it’s about solving problems creatively and making every asset work as part of a cohesive experience.</p><h2 id="education" tabindex="-1">Education <a class="header-anchor" href="#education" aria-label="Permalink to &quot;Education&quot;">​</a></h2><p>Animation BA (Hons) - 1st class University of the West of England, Bristol 2009 - 2012</p><p>Foundation Diploma - Distinction Northampton University September 2008 - June 2009</p><h2 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h2><ul><li>UI/UX Design &amp; Prototyping, Testing &amp; accessibility</li><li>Game Art &amp; Art Direction</li><li>Unity Technical Art &amp; VFX, including Shader &amp; Particle FX Creation</li><li>2D Rigging &amp; Animation in Spine, Unity Animation tools &amp; Adobe Animator</li><li>3D Modelling, Texturing &amp; Rigging</li><li>Art Pipeline Development</li><li>Marketing Art &amp; Creative Testing</li><li>Art Team Leadership &amp; Mentoring</li></ul><p>If you want to get in contact, you can email me at <a href="mailto:me@rebeccadeakin.com" target="_blank" rel="noreferrer">me@rebeccadeakin.com</a>. You can also view my <a href="http://www.linkedin.com/in/rebecca-deakin-03a69927" target="_blank" rel="noreferrer">linkedin profile</a>.</p>',12)]))}const h=i(o,[["render",r]]);export{g as __pageData,h as default};
